function SelectionToolbar({ rows }: { rows: Row[] }) {
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [count, setCount] = useState(0);

  function selectAll() {
    rows.forEach((r) => {
      setSelected(new Set(selected).add(r.id));
      setCount(count + 1);
    });
  }

  function logAndScroll() {
    flushSync(() => setCount(0));
    console.log("count after reset", count);
  }

  return (
    <div>
      <button onClick={selectAll}>Select all</button>
      <button onClick={logAndScroll}>Reset</button>
      <span>{count} selected</span>
    </div>
  );
}
